function(container, apiUrl, tables) {
    // 業務ロジックモジュールのインポート（グローバルスコープから取得）
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.aiLogic || {};

    // 売上データ収集ボタン
    const collectSalesBtn = container.querySelector('#collectSalesBtn');
    if (collectSalesBtn) {
        collectSalesBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;

                const tbody = container.querySelector('#salesDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    salesData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date || item.salesDate;
                        row.insertCell(1).textContent = item.productId;
                        row.insertCell(2).textContent = item.quantity;
                        row.insertCell(3).textContent = item.amount;
                    });
                }
                window.aivicNotify.success('売上データを収集しました');
            } catch (error) {
                window.aivicNotify.error('売上データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 商品別分析ボタン
    const analyzeByProductBtn = container.querySelector('#analyzeByProductBtn');
    if (analyzeByProductBtn) {
        analyzeByProductBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;
                const classifiedData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : {};
                const validData = filterValidProductData ? filterValidProductData(classifiedData) : classifiedData;

                const tbody = container.querySelector('#productAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(validData).forEach(([productId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = productId;
                        row.insertCell(1).textContent = data.totalQuantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || 0;
                        row.insertCell(3).textContent = data.averageDaily || 0;
                    });
                }
                window.aivicNotify.success('商品別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('商品別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 店舗別分析ボタン
    const analyzeByStoreBtn = container.querySelector('#analyzeByStoreBtn');
    if (analyzeByStoreBtn) {
        analyzeByStoreBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから売上データを取得
                const salesResponse = await window.aivicApi.list('sales', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;
                const classifiedData = classifySalesDataByStore ? classifySalesDataByStore(salesData) : {};

                const tbody = container.querySelector('#storeAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(classifiedData).forEach(([storeId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = storeId;
                        row.insertCell(1).textContent = data.totalQuantity || 0;
                        row.insertCell(2).textContent = data.totalAmount || 0;
                        row.insertCell(3).textContent = data.averageDaily || 0;
                    });
                }
                window.aivicNotify.success('店舗別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('店舗別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 天気データ収集ボタン
    const collectWeatherBtn = container.querySelector('#collectWeatherBtn');
    if (collectWeatherBtn) {
        collectWeatherBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIから天気データを取得
                const weatherResponse = await window.aivicApi.list('weather', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const weatherData = collectWeatherData ? collectWeatherData(weatherResponse.data, startDate, endDate) : weatherResponse.data;

                const tbody = container.querySelector('#weatherDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    weatherData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date;
                        row.insertCell(1).textContent = item.weather || item.condition;
                        row.insertCell(2).textContent = item.temperature;
                        row.insertCell(3).textContent = item.humidity;
                    });
                }
                window.aivicNotify.success('天気データを収集しました');
            } catch (error) {
                window.aivicNotify.error('天気データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // イベントデータ収集ボタン
    const collectEventBtn = container.querySelector('#collectEventBtn');
    if (collectEventBtn) {
        collectEventBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // APIからイベントデータを取得
                const eventResponse = await window.aivicApi.list('events', {
                    startDate: startDate,
                    endDate: endDate
                });

                // 業務ロジックで処理
                const eventData = collectEventData ? collectEventData(eventResponse.data, startDate, endDate) : eventResponse.data;

                const tbody = container.querySelector('#eventDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    eventData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date;
                        row.insertCell(1).textContent = item.eventName || item.name;
                        row.insertCell(2).textContent = item.eventType || item.type;
                        row.insertCell(3).textContent = item.impact;
                    });
                }
                window.aivicNotify.success('イベントデータを収集しました');
            } catch (error) {
                window.aivicNotify.error('イベントデータの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 相関分析ボタン
    const analyzeCorrelationBtn = container.querySelector('#analyzeCorrelationBtn');
    if (analyzeCorrelationBtn) {
        analyzeCorrelationBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // 各種データを取得
                const salesResponse = await window.aivicApi.list('sales', { startDate, endDate });
                const weatherResponse = await window.aivicApi.list('weather', { startDate, endDate });
                const eventResponse = await window.aivicApi.list('events', { startDate, endDate });

                // 業務ロジックで相関分析
                const salesData = collectSalesData ? collectSalesData(salesResponse.data, startDate, endDate) : salesResponse.data;
                const weatherData = collectWeatherData ? collectWeatherData(weatherResponse.data, startDate, endDate) : weatherResponse.data;
                const eventData = collectEventData ? collectEventData(eventResponse.data, startDate, endDate) : eventResponse.data;
                const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

                const weatherCorrelation = analyzeCorrelationSalesWeather ? analyzeCorrelationSalesWeather(salesData, weatherData) : {};
                const eventCorrelation = analyzeCorrelationSalesEvent ? analyzeCorrelationSalesEvent(salesData, eventData) : {};
                const seasonalCorrelation = analyzeCorrelationSalesSeason ? analyzeCorrelationSalesSeason(salesData, seasonalData) : {};

                // 結果を表示
                const tbody = container.querySelector('#correlationTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';

                    // 天気相関
                    const weatherRow = tbody.insertRow();
                    weatherRow.insertCell(0).textContent = '天気';
                    weatherRow.insertCell(1).textContent = weatherCorrelation.correlation || 0;
                    weatherRow.insertCell(2).textContent = weatherCorrelation.significance || 'N/A';

                    // イベント相関
                    const eventRow = tbody.insertRow();
                    eventRow.insertCell(0).textContent = 'イベント';
                    eventRow.insertCell(1).textContent = eventCorrelation.correlation || 0;
                    eventRow.insertCell(2).textContent = eventCorrelation.significance || 'N/A';

                    // 季節相関
                    const seasonRow = tbody.insertRow();
                    seasonRow.insertCell(0).textContent = '季節';
                    seasonRow.insertCell(1).textContent = seasonalCorrelation.correlation || 0;
                    seasonRow.insertCell(2).textContent = seasonalCorrelation.significance || 'N/A';
                }

                window.aivicNotify.success('相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 履歴比較ボタン
    const compareHistoryBtn = container.querySelector('#compareHistoryBtn');
    if (compareHistoryBtn) {
        compareHistoryBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // 期間の妥当性チェック
                const validationResult = validateComparisonPeriod ? validateComparisonPeriod(startDate, endDate) : { valid: true };
                if (!validationResult.valid) {
                    window.aivicNotify.error('比較期間が無効です: ' + validationResult.message);
                    return;
                }

                // 現在期間のデータ取得
                const currentResponse = await window.aivicApi.list('sales', { startDate, endDate });
                const currentData = collectSalesData ? collectSalesData(currentResponse.data, startDate, endDate) : currentResponse.data;

                // 履歴データ取得
                const historicalResponse = await window.aivicApi.list('sales', { 
                    startDate: validationResult.historicalStartDate,
                    endDate: validationResult.historicalEndDate
                });
                const historicalData = collectSalesData ? collectSalesData(historicalResponse.data, validationResult.historicalStartDate, validationResult.historicalEndDate) : historicalResponse.data;

                // 業務ロジックで比較
                const comparisonResult = compareWithHistoricalData ? compareWithHistoricalData(currentData, historicalData) : {};

                // 結果を表示
                const tbody = container.querySelector('#comparisonTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';

                    Object.entries(comparisonResult).forEach(([metric, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = metric;
                        row.insertCell(1).textContent = data.current || 0;
                        row.insertCell(2).textContent = data.historical || 0;
                        row.insertCell(3).textContent = data.difference || 0;
                        row.insertCell(4).textContent = (data.changeRate || 0) + '%';
                    });
                }

                window.aivicNotify.success('履歴比較を完了しました');
            } catch (error) {
                window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
            }
        });
    }

    // 初期化時に今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    const lastWeek = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');

    if (startDateInput && !startDateInput.value) {
        startDateInput.value = lastWeek;
    }
    if (endDateInput && !endDateInput.value) {
        endDateInput.value = today;
    }
}
